import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.Buc7gXeZ.js";const u=JSON.parse('{"title":"Dynamic Table Engine","description":"","frontmatter":{},"headers":[],"relativePath":"dynamic-table/index.md","filePath":"dynamic-table/index.md"}'),o={name:"dynamic-table/index.md"};function n(d,e,l,s,c,m){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="dynamic-table-engine" tabindex="-1">Dynamic Table Engine <a class="header-anchor" href="#dynamic-table-engine" aria-label="Permalink to &quot;Dynamic Table Engine&quot;">​</a></h1><p>A config-driven, Livewire + Flux UI data table engine built for this application. Tables are defined as PHP classes with a fluent column/filter API — no PowerGrid, Filament Tables, Rappasoft, or other third-party table package is used or required.</p><p>Every feature documented here is implemented and covered by Pest tests unless explicitly marked 🔮 Planned or ❌ Unsupported. See <a href="./testing">testing.md</a> for what&#39;s verified.</p><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><ul><li><strong>Core</strong> (<code>app/Support/DynamicTable/Core/</code>) — framework-facing column/filter/state definitions. No dependency on any Eloquent model, <code>Modules/*</code>, or Livewire/Flux.</li><li><strong>Query engine</strong> (<code>app/Support/DynamicTable/Query/</code>) — compiles a trusted table definition + validated client state into a real Eloquent query. No query ever runs in a Blade view.</li><li><strong>Livewire + Flux</strong> (<code>app/Livewire/DynamicTable/</code>, <code>resources/views/livewire/dynamic-table/</code>, <code>resources/views/components/dynamic-table/</code>) — one Livewire component per table instance, rendered with Flux UI Free components.</li><li><strong>Preference storage</strong> (<code>app/Support/DynamicTable/PreferenceStores/</code>, <code>app/Models/</code>) — Eloquent storage for per-user column preferences and personal saved views, behind swappable contracts.</li></ul><h2 id="feature-matrix" tabindex="-1">Feature matrix <a class="header-anchor" href="#feature-matrix" aria-label="Permalink to &quot;Feature matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Status</th></tr></thead><tbody><tr><td>Typed columns (Text/Number/Money/Date/DateTime/Boolean/Enum/Relation/Computed)</td><td>✅ Implemented</td></tr><tr><td>Relationship columns (BelongsTo, nested BelongsTo)</td><td>✅ Implemented</td></tr><tr><td>Global search (multi-column, relation-aware, multi-field on relations)</td><td>✅ Implemented</td></tr><tr><td>Search driver contract + Scout adapter</td><td>✅ Implemented — <code>DatabaseSearchDriver</code> (default), <code>ScoutSearchDriver</code></td></tr><tr><td>Typed filters + operators (text/number/date/boolean/enum/belongsTo)</td><td>✅ Implemented, including UI</td></tr><tr><td>Filter authorization (<code>Filter::visible()</code>, inherits from a same-key column)</td><td>✅ Implemented</td></tr><tr><td>Relationship filters (dotted key, BelongsToFilter)</td><td>✅ Implemented</td></tr><tr><td>Single &amp; additive multi-column sorting, PK tie-breaker</td><td>✅ Implemented — click to sort, shift-click to add/remove a sort, priority badges</td></tr><tr><td>Relation sorting: BelongsTo, HasMany/BelongsToMany with <code>-&gt;aggregate()</code></td><td>✅ Implemented</td></tr><tr><td>Relation sorting: HasOne, multi-level paths</td><td>❌ Unsupported</td></tr><tr><td>Standard &amp; simple pagination, per-table configurable</td><td>✅ Implemented — <code>protected function paginationMode(): string</code></td></tr><tr><td>Cursor pagination</td><td>❌ Unsupported — requesting it throws rather than silently falling back</td></tr><tr><td>Model-based default query (<code>protected ?string $model</code>)</td><td>✅ Implemented — <code>query()</code> no longer forced on every table</td></tr><tr><td>Column visibility (authorization boundary)</td><td>✅ Implemented, hardened — see security.md for the search-leak fix</td></tr><tr><td>User-controlled column visibility &amp; drag-and-drop ordering</td><td>✅ Implemented — Livewire 4 <code>wire:sort</code> + keyboard fallback</td></tr><tr><td>Persistent per-user preferences (column visibility/order/per-page)</td><td>✅ Implemented</td></tr><tr><td>Personal saved views, full UI (create/apply/rename-by-resave/delete/default/reset)</td><td>✅ Implemented</td></tr><tr><td>Active filter chips, applied-vs-draft indicator</td><td>✅ Implemented</td></tr><tr><td>Responsive Flux UI rendering</td><td>⚠️ Partial — desktop verified; mobile/RTL/dark-mode not yet verified (no browser test environment available in this session)</td></tr><tr><td>Authorization &amp; security enforcement</td><td>✅ Implemented, hardened across sessions (search leak, filter authorization, panel exposure)</td></tr><tr><td>Export</td><td>❌ Not implemented — <code>exportable()</code> is a config flag only</td></tr><tr><td>Row/bulk actions</td><td>❌ Not implemented</td></tr><tr><td>Summaries (count/sum/avg/min/max)</td><td>❌ Not implemented</td></tr><tr><td>Between/not-between two-value filter UI</td><td>✅ Implemented — dynamic two-input control, operator-specific hiding of the value control entirely for is_empty/is_not_empty/today/yesterday/this_week/this_month</td></tr><tr><td>Async <code>BelongsToFilter</code> picker</td><td>✅ Implemented — debounced search, min length, bounded/narrow-selected results, chips for multiple, escaped labels, previously-selected label resolution</td></tr><tr><td>Strict timezone-aware date filtering</td><td>✅ Implemented — strict <code>createFromFormat()</code> parsing with round-trip validation, per-filter timezone, DST-correct day boundaries computed in the filter&#39;s timezone then converted to the app timezone</td></tr></tbody></table><p>This matrix is maintained honestly — an earlier version of this document overstated completeness. See <code>.ai/dynamic-table/CHECKLIST.md</code> for the authoritative, session-by-session status.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Nothing to install. This engine ships in this repository&#39;s <code>app/</code> tree and uses only packages already present: Laravel 13, Livewire 4, Flux UI Free 2, Pest 5. No Composer/npm dependency was added to build it.</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><ol><li><a href="./quick-start">Quick start</a></li><li><a href="./columns">Columns</a></li><li><a href="./visibility-authorization">Visibility &amp; authorization</a></li><li><a href="./search">Search</a></li><li><a href="./filters">Filters</a></li><li><a href="./relationships">Relationships</a></li><li><a href="./sorting-pagination">Sorting &amp; pagination</a></li><li><a href="./preferences">Preferences</a></li><li><a href="./saved-views">Saved views</a></li><li><a href="./performance">Performance</a></li><li><a href="./security">Security</a></li><li><a href="./testing">Testing</a></li><li><a href="./extending">Extending</a></li><li><a href="./troubleshooting">Troubleshooting</a></li><li><a href="./package-extraction">Package extraction</a></li></ol><h2 id="canonical-example" tabindex="-1">Canonical example <a class="header-anchor" href="#canonical-example" aria-label="Permalink to &quot;Canonical example&quot;">​</a></h2><p><code>App\\Support\\DynamicTable\\Examples\\DemoTable</code> (rendered by <code>App\\Livewire\\DynamicTable\\DemoTableComponent</code>) is the reference table exercised by the automated test suite. Every example in these docs matches its real, tested API.</p>',14)])])}const h=t(o,[["render",n]]);export{u as __pageData,h as default};
